/* Wall-clock weekly layout in the schedule's explicit IANA timezone. */
const WeeklyCalendar=(()=>{
 const HOUR=64,MINUTE=HOUR/60;
 function local(value,timezone){const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value));const [day,time]=parts.split(' ');const [h,m]=time.split(':').map(Number);return {day,minute:h*60+m,time}}
 function plus(day,n){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
 function segments(rows,day,timezone){return rows.flatMap(row=>{const start=local(row.starts_at,timezone),end=local(row.ends_at,timezone);if(start.day>day||end.day<day||(end.day===day&&end.minute===0))return [];let from=start.day<day?0:start.minute,to=end.day>day?1440:end.minute;if(to<=from&&start.day===end.day&&start.day===day)to=Math.min(1440,from+(new Date(row.ends_at)-new Date(row.starts_at))/60000);if(to<=from)return [];return [{row,start:from,end:to,visualEnd:Math.min(1440,Math.max(to,from+20)),continued:start.day<day,continues:end.day>day&&end.minute!==0}]})}
 function lanes(events){const sorted=events.map(e=>({...e})).sort((a,b)=>a.start-b.start||b.end-a.end||a.row.id-b.row.id);let group=[],ends=[],maxEnd=-1;const result=[];function flush(){for(const e of group)result.push({...e,lanes:ends.length});group=[];ends=[];maxEnd=-1}for(const e of sorted){if(group.length&&e.start>=maxEnd)flush();let lane=ends.findIndex(end=>end<=e.start);if(lane<0)lane=ends.length;ends[lane]=e.visualEnd??e.end;group.push({...e,lane});maxEnd=Math.max(maxEnd,e.visualEnd??e.end)}flush();return result}
 function node(tag,value,className){const e=document.createElement(tag);if(value!==undefined)e.textContent=value;if(className)e.className=className;return e}
 function render(root,rows,options){const {weekStart,timezone,onCreate,onOpen}=options;const savedTop=root.scrollTop,initialized=root.dataset.initialized==='true';root.dataset.initialized='true';root.replaceChildren();root.className='time-calendar';root.setAttribute('aria-label','Недельный календарь, часовой пояс '+timezone);root.tabIndex=0;
 const week=node('div',undefined,'time-week'),now=local(new Date(),timezone),corner=node('div',undefined,'time-corner');corner.textContent='Время';week.append(corner);
 for(let i=0;i<7;i++){const day=plus(weekStart,i),head=node('div',undefined,'time-day-heading'+(day===now.day?' is-today':''));head.append(node('span',new Date(day+'T12:00:00Z').toLocaleDateString('ru-RU',{timeZone:'UTC',weekday:'short'})),node('strong',new Date(day+'T12:00:00Z').toLocaleDateString('ru-RU',{timeZone:'UTC',day:'numeric',month:'short'})));week.append(head)}
 const axis=node('div',undefined,'time-axis');axis.style.height=(24*HOUR)+'px';for(let h=0;h<24;h++){const label=node('span',String(h).padStart(2,'0')+':00');label.style.top=(h*HOUR)+'px';axis.append(label)}week.append(axis);
 const columns=[];for(let i=0;i<7;i++){const day=plus(weekStart,i),column=node('div',undefined,'time-day'+(day===now.day?' is-today':''));column.style.height=(24*HOUR)+'px';column.setAttribute('aria-label',day);columns.push({day,column});
 for(let slot=0;slot<48;slot++){const minute=slot*30,h=Math.floor(minute/60),m=minute%60,time=String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');const button=node('button',undefined,'time-slot');button.type='button';button.style.top=(minute*MINUTE)+'px';button.style.height=(30*MINUTE)+'px';button.setAttribute('aria-label','Создать урок '+day+' в '+time);button.title=day+' · '+time;button.disabled=day<now.day||(day===now.day&&minute<now.minute);button.onclick=()=>onCreate(day+'T'+time);column.append(button)}
 for(const e of lanes(segments(rows,day,timezone))){const row=e.row,start=local(row.starts_at,timezone),end=local(row.ends_at,timezone),status={scheduled:'Запланировано',completed:'Проведено',cancelled:'Отменено'}[row.status]||row.status;const button=node('button',undefined,'calendar-event '+row.status);button.type='button';button.style.top=(e.start*MINUTE)+'px';button.style.height=Math.max(1,(e.visualEnd-e.start)*MINUTE-2)+'px';button.style.left='calc('+(e.lane*100/e.lanes)+'% + 2px)';button.style.width='calc('+(100/e.lanes)+'% - 4px)';const period=(e.continued?'Продолжение · ':'')+start.time+'–'+end.time;button.append(node('strong',row.student_name||'Занятие'),node('span',period),node('span',row.topic||status));button.title=[row.student_name,period,row.topic,status].filter(Boolean).join(' · ');button.setAttribute('aria-label',button.title);button.onclick=()=>onOpen(row);column.append(button)}week.append(column)}root.append(week);
 const marker=node('div',undefined,'calendar-now');marker.setAttribute('aria-hidden','true');const update=()=>{const current=local(new Date(),timezone),target=columns.find(c=>c.day===current.day);if(target){marker.style.top=(current.minute*MINUTE)+'px';target.column.append(marker)}else marker.remove()};update();const timer=setInterval(update,60000);
 root.scrollTop=initialized?savedTop:Math.max(0,(8*HOUR)-20);return ()=>clearInterval(timer)}
 return {local,plus,segments,lanes,render};
})();
